{{.bw_monitor_turn = {{default::{{@gabi_dependency_turn}}::0}}}}
{{.bw_monitor_influence = {{default::{{@gabi_tracker_influence}}::{{default::{{var::gabi_tracker_influence}}::7}}}}}}

{{if::{{rejectedSwipe}}}}
{{.bw_swipe_previous = {{split::{{split::{{rejectedSwipe}}::"previous":"::1}}::"::0}}}}
{{.bw_swipe_turn = {{split::{{split::{{rejectedSwipe}}::"turn":"::1}}::"::0}}}}
{{if::{{number::{{.bw_swipe_previous}}}}}}
{{.bw_monitor_load = {{.bw_swipe_previous}}}}
